package com.mamtrex.hospital.staff;
import com.mamtrex.hospital.organization.Branch; import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="staff_members") public class StaffMember extends BaseEntity { private String employeeCode; private String fullName; private String profession; private String licenseNumber; private String department; /* Branch ownership (docs/plan3.md Task 4): workflow creates derive it from the acting context, never client input; null is the deliberate legacy seam for pre-Task-4 rows, which stay invisible through branch-scoped endpoints. */ @ManyToOne @JoinColumn(name="branch_id") private Branch branch; protected StaffMember(){} public StaffMember(Branch branch, String employeeCode, String fullName, String profession, String licenseNumber, String department){this.branch=branch; this.employeeCode=employeeCode; this.fullName=fullName; this.profession=profession; this.licenseNumber=licenseNumber; this.department=department;} public String getEmployeeCode(){return employeeCode;} public String getFullName(){return fullName;} public String getProfession(){return profession;} public String getLicenseNumber(){return licenseNumber;} public String getDepartment(){return department;} public Branch getBranch(){return branch;} }
